public function test_suporte_registra_ciencia_e_o_ato_vai_para_a_auditoria(): void
{
    [$account, $client] = $this->cenario();
    $this->fakeLeituraComSucesso();

    $superAdmin = User::factory()->create();
    $superAdmin->forceFill(['is_super_admin' => true])->save();
    $casa = Account::factory()->create();
    AccountUser::create(['account_id' => $casa->getKey(), 'user_id' => $superAdmin->getKey(), 'role' => 'admin']);
    $this->selectBusinessAccount($superAdmin, $casa->getKey());
    $superAdmin->refresh();

    $this->actingAs($superAdmin, 'web')
        ->postJson("/api/v1/support/accounts/{$account->getKey()}/enter")
        ->assertOk();

    $this->actingAs($superAdmin, 'web')
        ->postJson($this->rota($client, 82838), ['ciencia' => true])
        ->assertOk()
        ->assertJsonPath('data.id', 82838);

    $this->assertTrue(
        SupportAccessLog::query()
            ->where('super_admin_user_id', $superAdmin->getKey())
            ->where('account_id', $account->getKey())
            ->where('action', 'ciencia')
            ->where('metadata->resource', 'serpro_messages')
            ->where('metadata->resource_id', 82838)
            ->exists(),
    );
}

public function test_escrita_em_modo_suporte_registra_a_auditoria_sem_segredo(): void
{
    $alvo = Account::factory()->create();

    $super = User::factory()->create(['is_super_admin' => true]);
    $casa = Account::factory()->create();
    AccountUser::create(['account_id' => $casa->getKey(), 'user_id' => $super->getKey(), 'role' => 'admin']);
    $this->selectBusinessAccount($super, $alvo->getKey());

    ['bytes' => $bytes, 'file' => $arquivo] = $this->pfx('escritorio.p12');

    $this->actingAs($super->refresh(), 'web')
        ->post(self::ROTA, ['certificate' => $arquivo, 'password' => self::SENHA], $this->jsonHeaders())
        ->assertOk();

    $log = SupportAccessLog::query()->sole();

    $this->assertSame($super->getKey(), $log->super_admin_user_id);
    $this->assertSame($alvo->getKey(), $log->account_id);
    $this->assertSame('create', $log->action);
    $this->assertSame('account_certificates', $log->metadata['resource'] ?? null);

    // O que a auditoria registra é quem fez o quê: o documento, que a API
    // publica. Nem o arquivo, nem a senha, nem o texto cifrado.
    $this->assertSame(self::CNPJ, $log->metadata['document'] ?? null);

    $registro = (string) $log->toJson();

    $this->assertStringNotContainsString(self::SENHA, $registro);
    $this->assertStringNotContainsString(base64_encode($bytes), $registro);
    $this->assertStringNotContainsString(
        (string) AccountCertificate::query()->sole()->getRawOriginal('certificate_encrypted'),
        $registro,
    );
}

public function test_suporte_dispara_em_conta_alheia_com_flag_e_auditoria(): void
{
    Queue::fake();
    $this->canalConectado();

    $superAdmin = $this->superAdminWithOwnAccount();
    $this->actingAs($superAdmin, 'web')
        ->postJson("/api/v1/support/accounts/{$this->account->getKey()}/enter")
        ->assertOk();

    $this->postJson($this->dispatchUrl(), ['competence' => '2026-01', 'artifact' => 'guia'])
        ->assertAccepted();

    $dispatch = WhatsAppDispatch::query()->first();
    $this->assertNotNull($dispatch);
    $this->assertSame($this->account->getKey(), $dispatch->account_id);
    $this->assertTrue((bool) $dispatch->dispatched_in_support);
    $this->assertSame($superAdmin->getKey(), $dispatch->dispatched_by_user_id);
