public function test_suporte_escreve_em_conta_alheia_com_auditoria(): void
{
    $superAdmin = $this->superAdminWithOwnAccount();
    $this->actingAs($superAdmin, 'web')
        ->postJson("/api/v1/support/accounts/{$this->account->getKey()}/enter")
        ->assertOk();

    $this->postJson($this->contactsUrl(), [
        'label' => 'Contador',
        'channel' => 'whatsapp',
        'value' => '11987654321',
    ])->assertCreated();

    $contato = ClientDispatchContact::query()->sole();
    $this->assertSame($this->account->getKey(), $contato->account_id);

    $log = SupportAccessLog::query()
        ->where('super_admin_user_id', $superAdmin->getKey())
        ->latest('id')
        ->first();
    $this->assertNotNull($log);
    $this->assertSame('create', $log->action);
    $this->assertSame('client_dispatch_contacts', $log->metadata['resource'] ?? null);
    $this->assertSame($contato->getKey(), $log->metadata['resource_id'] ?? null);

    $this->deleteJson("{$this->contactsUrl()}/{$contato->getKey()}")->assertNoContent();

    $logRemocao = SupportAccessLog::query()
        ->where('super_admin_user_id', $superAdmin->getKey())
        ->latest('id')
        ->first();
    $this->assertSame('delete', $logRemocao->action);
}

public function test_suporte_dispara_em_conta_alheia_com_auditoria_por_disparo(): void
{
    Queue::fake();
    $this->canalConectado();
    $socio = $this->contato(null, 'whatsapp', '5511987654321');
    $socio2 = $this->contato('Sócio 2', 'whatsapp', '5511912345678');

    $superAdmin = $this->superAdminWithOwnAccount();
    $this->actingAs($superAdmin, 'web')
        ->postJson("/api/v1/support/accounts/{$this->account->getKey()}/enter")
        ->assertOk();

    $this->postJson($this->sendGuidesUrl(), [
        'contact_ids' => [$socio->getKey(), $socio2->getKey()],
    ])->assertAccepted();

    $dispatches = WhatsAppDispatch::query()->orderBy('id')->get();
    $this->assertCount(2, $dispatches);

    foreach ($dispatches as $dispatch) {
        $this->assertSame($this->account->getKey(), $dispatch->account_id);
        $this->assertTrue((bool) $dispatch->dispatched_in_support);
        $this->assertSame($superAdmin->getKey(), $dispatch->dispatched_by_user_id);
        $this->assertNotNull($dispatch->support_access_log_id);
    }

    // Um registro de auditoria por Disparo — a trilha é 1:1.
    $logs = SupportAccessLog::query()
        ->where('action', 'dispatch')
        ->where('metadata->resource', 'whatsapp_dispatches')
        ->count();
    $this->assertSame(2, $logs);
}

