public function test_upload_e_desligamento_em_suporte_gravam_logwrite(): void
{
    $suporte = User::factory()->create(['is_super_admin' => true]);
    $casa = Account::factory()->create();
    AccountUser::create(['account_id' => $casa->getKey(), 'user_id' => $suporte->getKey(), 'role' => 'admin']);
    $this->selectBusinessAccount($suporte, $casa->getKey());

    $alvo = Account::factory()->create();
    $client = Client::factory()->company()->create(['account_id' => $alvo->getKey()]);

    $this->actingAs($suporte->refresh(), 'web')
        ->postJson("/api/v1/support/accounts/{$alvo->getKey()}/enter")
        ->assertOk();

    $this->post("/api/v1/clients/{$client->getKey()}/certificate", [
        'password' => 'senha-do-certificado',
        'certificate' => $this->pfxUpload('cliente.pfx', 'senha-do-certificado'),
    ], ['Accept' => 'application/json'])->assertOk();

    // O upload grava a fonte enfileirada; a remoção registra o que existia.
    $log = SupportAccessLog::query()
        ->where('super_admin_user_id', $suporte->getKey())
        ->where('account_id', $alvo->getKey())
        ->where('action', 'certificate')
        ->sole();

    $this->assertSame('clients', $log->metadata['resource']);
    $this->assertSame($client->getKey(), $log->metadata['resource_id']);
    $this->assertSame(['nfe_distribuicao'], $log->metadata['sources'] ?? null);
    $this->assertStringNotContainsString('senha-do-certificado', json_encode($log->metadata));
    $certificateId = $client->fresh(['currentCertificate'])->currentCertificate->getKey();

    $this->deleteJson("/api/v1/clients/{$client->getKey()}/certificate")->assertNoContent();

    $this->assertSame(
        1,
        SupportAccessLog::query()->where('action', 'certificate-remove')->count(),
    );
    $removal = SupportAccessLog::query()->where('action', 'certificate-remove')->sole();
    $this->assertSame([
        'resource' => 'clients',
        'resource_id' => $client->getKey(),
        'certificate_id' => $certificateId,
    ], $removal->metadata);
}

public function test_captura_em_modo_suporte_registra_a_escrita(): void
{
    Bus::fake();

    $suporte = User::factory()->create(['is_super_admin' => true]);
    $casa = Account::factory()->create();
    AccountUser::create([
        'account_id' => $casa->getKey(),
        'user_id' => $suporte->getKey(),
        'role' => 'admin',
    ]);
    $this->selectBusinessAccount($suporte, $casa->getKey());

    $alvo = Account::factory()->create();
    $cliente = $this->clienteComCertificado($alvo, 'Cliente Da Conta Alvo');
    $certificado = ClientCertificate::query()->where('client_id', $cliente->getKey())->sole();

    $this->actingAs($suporte->refresh(), 'web')
        ->postJson("/api/v1/support/accounts/{$alvo->getKey()}/enter")
        ->assertOk();

    $this->postJson("/api/v1/fiscal/clients/{$cliente->getKey()}/capture")
        ->assertStatus(202)
        ->assertJsonPath('data.client_id', $cliente->getKey());

    // A escrita do super_admin dentro da conta alheia é poder total, e por
    // isso ela é auditada: a captura é a única escrita do módulo, então é
    // a única que aparece aqui.
    $log = SupportAccessLog::query()
        ->where('super_admin_user_id', $suporte->getKey())
        ->where('account_id', $alvo->getKey())
        ->where('action', 'capture')
        ->sole();

    $this->assertSame('fiscal', $log->metadata['resource']);
    $this->assertSame($cliente->getKey(), $log->metadata['resource_id']);
    $this->assertSame('nfe_distribuicao', $log->metadata['source']);

    // Só o id do cliente e a fonte: o material do cofre do cliente não
    // entra numa auditoria.
    $this->assertSame(['resource', 'resource_id', 'source'], array_keys($log->metadata));
    $this->assertStringNotContainsString((string) $certificado->storage_path, json_encode($log->metadata, JSON_THROW_ON_ERROR));
    $this->assertStringNotContainsString('password_encrypted', json_encode($log->metadata, JSON_THROW_ON_ERROR));

    // A recusa por bloqueio responde 409 e de propósito não deixa rastro de
    // auditoria: uma recusa não é escrita — a posição do fisco não foi
    // consumida e nada mudou na conta — e a tabela de suporte registra
    // escritas, com verbo de escrita. É a regra de todo `logWrite` do
    // código: nenhum deles acompanha uma recusa.
    //
    // As duas asserções abaixo existem para que o comentário e o código não
    // voltem a divergir: quem um dia ler isto e achar que falta a
    // auditoria da recusa quebra o teste, e não mente sobre o rastro.
    $this->cursor($cliente, ['last_run_at' => now(), 'blocked_until' => now()->addHour()]);

    $this->postJson("/api/v1/fiscal/clients/{$cliente->getKey()}/capture")->assertStatus(409);

    // Continua havendo um despacho só e uma entrada só: as duas são as do
    // 202 acima, e a recusa não acrescentou nenhuma das duas.
    Bus::assertDispatchedTimes(CaptureFiscalDocumentsJob::class, 1);

    $this->assertSame(1, SupportAccessLog::query()
        ->where('super_admin_user_id', $suporte->getKey())
        ->where('account_id', $alvo->getKey())
        ->where('action', 'capture')
        ->count(), 'a recusa por bloqueio não é uma escrita e não pode virar entrada de auditoria');
}

public function test_detalhe_e_download_de_outra_conta_dependem_do_suporte_ter_entrado(): void
{
    $suporte = User::factory()->create(['is_super_admin' => true]);
    $casa = Account::factory()->create();
    AccountUser::create([
        'account_id' => $casa->getKey(),
        'user_id' => $suporte->getKey(),
        'role' => 'admin',
    ]);
    $this->selectBusinessAccount($suporte, $casa->getKey());

    $alvo = Account::factory()->create();
    $documento = FiscalDocument::factory()->withStoredXml()->create([
        'client_id' => $this->clienteComCertificado($alvo, 'Cliente Da Conta Alvo')->getKey(),
        'account_id' => $alvo->getKey(),
    ]);

    $this->actingAs($suporte->refresh(), 'web');

    // Antes de entrar, a conta corrente do super_admin é a dele: o id alheio
    // é inexistente para ele.
    $this->getJson("/api/v1/fiscal/documents/{$documento->getKey()}")->assertNotFound();
    $this->get("/api/v1/fiscal/documents/{$documento->getKey()}/xml")->assertNotFound();

    // Em modo suporte a conta corrente é a alvo, e o documento abre: a
    // restrição é por conta corrente, não por identidade do operador.
    $this->postJson("/api/v1/support/accounts/{$alvo->getKey()}/enter")->assertOk();

    $this->getJson("/api/v1/fiscal/documents/{$documento->getKey()}")
        ->assertOk()
        ->assertJsonPath('data.id', $documento->getKey());
    $this->get("/api/v1/fiscal/documents/{$documento->getKey()}/xml")->assertOk();
}

public function test_a_auditoria_da_remocao_nomeia_a_linha_que_o_cofre_removeu(): void
{
    $alvo = Account::factory()->create();

    $super = User::factory()->create(['is_super_admin' => true]);
    $casa = Account::factory()->create();
    AccountUser::create(['account_id' => $conta->getKey(), 'user_id' => $super->getKey(), 'role' => 'admin']);
    $this->selectBusinessAccount($super, $alvo->getKey());
    $super = $super->refresh();

    // A conta tem uma linha anterior fora de vigência, de um e-CNPJ que já
    // foi trocado, e a corrente por último. O que se fixa aqui é que o
    // `document` e o `id` registrados são os da linha **removida** — a que
    // estava valendo —, e não os de qualquer outra linha da conta.
    $historicoAntigo = AccountCertificate::factory()->replaced()->create([
        'account_id' => $alvo->getKey(),
        'document' => '11222333000181',
    ]);

    ['file' => $arquivo] = $this->pfx('escritorio.p12');

    $this->actingAs($super, 'web')
        ->post(self::ROTA, ['certificate' => $arquivo, 'password' => self::SENHA], $this->jsonHeaders())
        ->assertOk();

    $corrente = AccountCertificate::currentFor($alvo->getKey());

    $this->assertNotNull($corrente);
    $this->assertSame(self::CNPJ, $corrente->document);
    $this->assertNotSame($historicoAntigo->getKey(), $corrente->getKey());

    // A remoção, com a contagem de leituras armada: o que se quer ver é que a
    // linha corrente é lida **uma vez**. O controller lia a corrente para
    // montar a auditoria e o cofre a lia de novo dentro da transação — duas
    // queries para uma linha, e duas chances de verem linhas diferentes.
    // O cofre devolve a linha que removeu, e é dela que a auditoria sai.
    $this->contando(function () use ($super): void {
        $this->actingAs($super, 'web')->deleteJson(self::ROTA)->assertNoContent();
    });

    $this->assertSame(1, $this->leituras, 'A linha corrente foi lida mais de uma vez durante a remoção.');

    $log = SupportAccessLog::query()
        ->where('action', 'delete')
        ->sole();

    $this->assertSame($corrente->getKey(), $log->metadata['resource_id'] ?? null);
    $this->assertSame(self::CNPJ, $log->metadata['document'] ?? null);

    // Uma linha removida, e só a que estava valendo.
    $this->assertNotNull($corrente->refresh()->removed_at);
    $this->assertNotNull($historicoAntigo->refresh()->replaced_at);
    $this->assertNull($historicoAntigo->refresh()->removed_at);
    $this->assertNull(AccountCertificate::currentFor($alvo->getKey()));
}
